public class DateTools {
    /** Returns true if year is a leap year. A year is a leap year if it is divisible by 4, except that
     *  a year divisible by 100 is a leap year only if it is also divisible by 400. */
    public static boolean isLeapYear(int year) { /* to be implemented in part (a) */ }

    /** Returns the number of days in month (1 through 12) of year; see part (b). */
    public static int daysInMonth(int month, int year) { /* to be implemented in part (b) */ }
}
```

